@needs_weights
@pytest.mark.parametrize("clean, corrupted, io_t, subj_t", PAIRS,
                         ids=[p[0][:18] for p in PAIRS])
def test_the_sign_holds_on_prompts_chosen_independently(
    lm, clean, corrupted, io_t, subj_t
):
    """Each pair measured on its own tokens.

    The fixture guard matters more here than the assertion: a pair whose
    corruption did not flip the preference would fail this test for a reason
    that has nothing to do with the direction under test.
    """
    clean_diff, corr_diff = _measure(lm, clean, corrupted, io_t, subj_t)

    assert clean_diff > 0, (
        f"{clean!r} does not prefer the IO token ({io_t!r}): "
        f"logit_diff={clean_diff:.4f}. This prompt is not an IOI pair, so a "
        f"failure below would not be about causal direction."
    )
    assert corr_diff < 0, (
        f"{corrupted!r} still prefers the IO token: logit_diff="
        f"{corr_diff:.4f}; the corruption did not take"
    )
    assert clean_diff > corr_diff, (
        f"corruption moved the metric the wrong way: clean {clean_diff:.4f} "
        f"is not above corrupted {corr_diff:.4f}"
    )


@needs_weights
def test_the_weak_pair_is_reported_as_weak_not_as_a_sign_failure(lm):
    """A pair that does not work must be distinguishable from a broken sign.

    Measured: `Raj gave the book to Priya` gives clean -2.7479 and corrupted
    -3.8969. The gap is +1.1491, the right sign, but the clean run does not
    prefer the IO token -- so it is not a usable IOI pair.

    This is the distinction the four tests above cannot make on their own: if
    every prompt worked, a regression that broke the direction everywhere
    would look identical to a suite that never tested anything.
    """
    clean_diff, corr_diff = _measure(lm, *WEAK_PAIR)

    assert clean_diff > corr_diff, (
        "the weak pair's gap flipped sign entirely; if this has started "
        "failing, the direction itself has regressed rather than this pair "
        "being unsuitable"
    )
    assert clean_diff <= 0, (
        f"the weak pair now prefers the IO token ({clean_diff:.4f}); it has "
        f"become a usable IOI pair and should be promoted into PAIRS"
    )


@needs_weights
def test_the_gap_scales_across_pairs_and_is_never_tiny_for_a_usable_pair(lm):
    """A usable pair has a gap comfortably clear of zero.

    This is the precondition for the normalisation in gap 5, stated as its
    own test so a future pair added to `PAIRS` cannot quietly introduce a
    denominator near zero.
    """
    gaps = []
    for clean, corrupted, io_t, subj_t in PAIRS:
        clean_diff, corr_diff = _measure(lm, clean, corrupted, io_t, subj_t)
        if clean_diff > 0 and corr_diff < 0:
            gaps.append(clean_diff - corr_diff)

    assert gaps, "no pair produced a usable IOI baseline"
    smallest = min(gaps)
    assert smallest > 1.0, (
        f"a usable pair has a gap of only {smallest:.4f}; normalising by a gap "
        f"this small amplifies rounding into a large apparent effect"
    )


