@needs_weights
def test_a_prompt_pair_with_no_preference_produces_no_usable_denominator(lm):
    """The same token on both sides gives a gap of exactly zero.

    Measured: comparing `" David"` against itself yields `logit_diff` 0.0000
    on both sides, so `denom = clean - corrupted` is 0.0 and every normalised
    effect divides by it.

    The refusal has to happen, because `inf` is the most confident-looking
    number a research tool can emit and here it would mean "this prompt
    measured nothing".
    """
    engine = lm._engine()
    tokenizer = engine._tokenizer
    same = tokenizer(" David")["input_ids"][0]

    clean = lm.baseline("The nurse called David", same, same)["logit_diff"]
    corrupted = lm.baseline("The nurse called David", same, same)["logit_diff"]
    denom = clean - corrupted

    assert denom == 0.0, (
        f"fixture assumption broken: the degenerate pair gave denom="
        f"{denom}, not 0. This test is about the zero-denominator case."
    )

    assert lm.denominator_is_usable(denom) is False, (
        "a zero gap was accepted as a usable denominator; every normalised "
        "effect through it is inf, and inf reads as the strongest possible "
        "result rather than as no measurement"
    )

    # And normalisation must refuse rather than divide.
    normalised = lm.normalise_effect(1.0, denom)
    assert normalised is None, (
        f"normalising against a zero denominator returned {normalised}; it "
        f"must return None so the caller reports the measurement as "
        f"unavailable"
    )


@needs_weights
@pytest.mark.parametrize("denom", [0.0, 1e-12, 1e-6, 0.0099])
def test_normalisation_refuses_degenerate_denominators(lm, denom):
    """Including the near-zero band, not just exact zero.

    A threshold of exactly zero would accept 1e-12 and produce a number of
    order 1e12, which is exactly the "small noisy effect reported as enormous"
    failure the review asks about.

    The last case is the boundary and it earned its place: an implementation
    with `MIN_DENOMINATOR = 1e-6` and `>=` accepted exactly 1e-6, yielding a
    quotient of 1e6. So the floor is 0.01 -- a gap that small amplifies an
    order-1 effect past 100, which is larger than the gap it claims to
    normalise.
    """
    assert lm.denominator_is_usable(denom) is False, (
        f"a denominator of {denom} was treated as usable; normalising by it "
        f"turns rounding error into an arbitrarily large apparent effect"
    )
    assert lm.normalise_effect(1.0, denom) is None


@needs_weights
def test_normalisation_accepts_a_healthy_denominator(lm):
    """The negative control: a real gap must still normalise."""
    assert lm.denominator_is_usable(3.9) is True
    value = lm.normalise_effect(1.0, 3.9)
    assert value is not None and value == pytest.approx(1.0 / 3.9)


